	function get_ledger_hisab($pid)
	{
        $this->db->trans_start();
		$vcamnt = $this->getvoucheramount($pid);
		$vccrdtby = $this->getvouchercollectedbyamount($pid);
		$openingbal = $this->getopeningbal($pid);
		$arr = 0;
		$arr = $arr + ((!empty($vcamnt)) ? $vcamnt[0]['Amount'] : 0);
		$arr = $arr - ((!empty($vccrdtby)) ? $vccrdtby[0]['Amount'] : 0);
		$arr = $arr + ((!empty($openingbal)) ? $openingbal[0]['openingbalance'] : 0);
		$this->db->select('Tb_Date_shift_party_entry.net_profit');
		$this->db->from('Tb_Date_shift_party_entry');
		$this->db->where('Tb_Date_shift_party_entry.PartyId', $pid);
